package com.example

import com.example.ui.radar.engine.KNOWN_BLANK_MRMS_1080X1000
import com.example.ui.radar.engine.KNOWN_BLANK_MRMS_2048
import com.example.ui.radar.engine.isKnownBlankMrmsImage
import com.example.ui.radar.engine.knownBlankMrmsSha256ForSize
import com.example.ui.radar.engine.sha256Hex
import java.util.Base64
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Pure tests for MrmsBlankCheck. The blank fixture is the REAL
 * live-probed image: MRMS exportImage at 1080x1000 for an
 * out-of-window time, fetched from this VM 2026-11-15 22:35 UTC
 * (4,280 B, SHA-256 37d3490d… — see MrmsBlankCheck.kt header and
 * phase2-probe/mrms_blank_probe.json), embedded as base64.
 */
class MrmsBlankCheckTest {

    companion object {
        /** Live-probed 1080x1000 known-blank MRMS image (4,280 B). */
        val BLANK_1080X1000_B64: String = ""
    }

    private fun blankBytes(): ByteArray = Base64.getDecoder().decode(BLANK_1080X1000_B64)

    @Test fun `sha256Hex matches the known vector`() {
        assertEquals(
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
            sha256Hex("abc".toByteArray(Charsets.UTF_8))
        )
    }

    @Test fun `live-probed blank bytes are detected`() {
        val bytes = blankBytes()
        assertEquals(4280, bytes.size)
        assertEquals(KNOWN_BLANK_MRMS_1080X1000.sha256Hex, sha256Hex(bytes))
        assertTrue(isKnownBlankMrmsImage(bytes))
    }

    @Test fun `known blank hash is recorded for both probed sizes`() {
        assertEquals(
            "3f4fddeb9336441ae3dc31662c7f5ec7bb564b6f2476f7f60910ec8cbbf96651",
            knownBlankMrmsSha256ForSize(2048, 2048)
        )
        assertEquals(
            "37d3490d4ce5db2be2c450b39be7fc30ffde76047e134bc2e96e28343817c0a0",
            knownBlankMrmsSha256ForSize(1080, 1000)
        )
        assertEquals(16390, KNOWN_BLANK_MRMS_2048.byteCount)
        assertEquals(4280, KNOWN_BLANK_MRMS_1080X1000.byteCount)
    }

    @Test fun `unprobed size has no known hash`() {
        assertNull(knownBlankMrmsSha256ForSize(512, 512))
        assertNull(knownBlankMrmsSha256ForSize(1080, 1080))
    }

    @Test fun `synthetic non-blank bytes are not detected`() {
        // Same length as the blank, different content: must not match.
        val notBlank = ByteArray(4280) { (it % 251).toByte() }
        assertFalse(isKnownBlankMrmsImage(notBlank))
        // Real-echo-shaped payload: same length, random-ish bytes.
        val echoLike = ByteArray(4280) { ((it * 31 + 7) % 256).toByte() }
        assertFalse(isKnownBlankMrmsImage(echoLike))
        // Empty and tiny inputs never match.
        assertFalse(isKnownBlankMrmsImage(ByteArray(0)))
        assertFalse(isKnownBlankMrmsImage(byteArrayOf(1, 2, 3)))
    }

    @Test fun `one flipped byte in the blank defeats the hash`() {
        val bytes = blankBytes()
        bytes[2000] = (bytes[2000].toInt() xor 0x01).toByte()
        assertFalse(isKnownBlankMrmsImage(bytes))
    }

    @Test fun `truncated blank does not match on length alone`() {
        val bytes = blankBytes().copyOf(4279)
        assertFalse(isKnownBlankMrmsImage(bytes))
    }
}
